@media(max-width:700px){.virtual-controls{inset-inline:8px;bottom:8px;align-items:flex-end;gap:8px}.virtual-stick{flex:0 0 84px;width:84px;height:58px}.virtual-actions{display:grid;grid-template-columns:repeat(4,32px);grid-template-rows:repeat(2,32px);gap:4px;align-items:center}.virtual-button,.jump-button,.contract-button{width:32px;height:32px;margin:0;font-size:10px}.attack-button{border-color:rgba(223,65,55,.9);background:rgba(143,43,39,.88)}.contract-button,.pause-button{font-size:8px}.hud-bottom-left,.hud-bottom-right{bottom:83px}}
