.contract-menu-overlay,.pause-overlay{position:absolute;inset:0;z-index:8;display:grid;place-items:center;padding:18px;background:rgba(9,10,14,.82);backdrop-filter:blur(4px)}.quick-menu{width:min(330px,94%);padding:22px;border:1px solid #66534c;background:linear-gradient(145deg,#222126,#15161a);box-shadow:0 14px 50px #000b;text-align:left}.quick-menu-kicker{font:9px var(--mono);letter-spacing:.16em;color:#e18b6e}.quick-menu h2{margin:8px 0 16px;font-size:22px;letter-spacing:-.04em}.quick-menu p{font-size:12px;color:#b1afb0;line-height:1.5}.quick-contract,.quick-menu-close,.resume-button{width:100%;margin-top:7px;padding:10px 11px;border:1px solid #39383d;background:#1a1b20;text-align:left;font:700 11px var(--mono);letter-spacing:.04em;cursor:pointer}.quick-contract:hover,.quick-menu-close:hover,.resume-button:hover{border-color:#d25a4d;background:#292126}.quick-contract small{display:block;margin:4px 0 0 28px;color:#99969a;font:8px var(--mono);letter-spacing:.08em}.quick-menu-close,.resume-button{margin-top:14px;text-align:center;color:#e7b98c}.pause-card{text-align:center}.pause-card .quick-menu-kicker{display:block}.pause-card .resume-button{background:#a53d36;color:#fff;text-align:center}

/* Compact, full-screen game view for phones held horizontally. */
@media (max-width: 900px) and (max-height: 600px) and (orientation: landscape) {
  html,
  body {
    width: 100%;
    height: 100%;
    min-height: 0;
    overflow: hidden;
  }

  .app-shell {
    width: 100%;
    max-width: none;
    height: 100dvh;
    margin: 0;
    padding: 0;
  }

  .topbar,
  .intro-row,
  .intel-panel,
  .control-strip {
    display: none;
  }

  .game-layout {
    display: block;
    width: 100%;
    height: 100dvh;
    margin: 0;
  }

  .game-column {
    display: grid;
    width: 100%;
    height: 100dvh;
    min-width: 0;
    place-items: center;
  }

  .game-frame {
    display: grid;
    width: 100%;
    height: 100%;
    padding: 0;
    border: 0;
    background: #08090c;
    place-items: center;
  }

  .frame-top,
  .frame-bottom {
    display: none;
  }

  .viewport {
    width: min(100vw, 177.7778dvh);
    height: min(100dvh, 56.25vw);
    margin: auto;
    aspect-ratio: 16 / 9;
  }

  .virtual-controls.enabled {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    padding: 8px max(10px, env(safe-area-inset-right)) max(8px, env(safe-area-inset-bottom)) max(10px, env(safe-area-inset-left));
  }

  .virtual-stick {
    flex: 0 0 88px;
    width: 88px;
    height: 58px;
  }

  .virtual-actions {
    display: grid;
    grid-template-columns: repeat(3, clamp(36px, 10vh, 46px));
    grid-template-rows: repeat(2, clamp(36px, 10vh, 46px));
    gap: clamp(3px, 1vw, 7px);
    align-items: center;
    justify-items: center;
  }

  .virtual-button,
  .virtual-button.jump-button,
  .virtual-button.contract-button {
    width: clamp(36px, 10vh, 46px);
    height: clamp(36px, 10vh, 46px);
    margin: 0;
    border-radius: 50%;
    font-size: 12px;
  }

  .weapon-button { grid-area: 1 / 1; }
  .dash-button { grid-area: 1 / 2; }
  .contract-button { grid-area: 1 / 3; }
  .interact-button { grid-area: 2 / 1; }
  .jump-button { grid-area: 2 / 2; }
  .attack-button {
    grid-area: 2 / 3;
    border-color: rgba(223, 65, 55, .9);
    background: rgba(143, 43, 39, .9);
  }

  .virtual-controls .pause-button {
    position: absolute;
    top: max(8px, env(safe-area-inset-top));
    left: max(8px, env(safe-area-inset-left));
    width: 40px;
    height: 32px;
    border-radius: 7px;
    font-size: 9px;
  }

  .hud-bottom-left,
  .hud-bottom-right {
    bottom: clamp(108px, 30vh, 132px);
  }
}

