(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  ctx.imageSmoothingEnabled = false;
  const W = canvas.width, H = canvas.height, FLOOR = 226, WORLD = 2600;
  const $ = (id) => document.getElementById(id);
  const ui = { start:$('start-overlay'), result:$('result-overlay'), controls:$('virtual-controls'), boss:$('boss-bar'), bossMeter:$('boss-meter'), hearts:$('hearts'), health:$('health-text'), debt:$('debt-value'), debtMeter:$('debt-meter'), kills:$('kill-count'), cash:$('cash-value'), objKills:$('objective-count'), objDebt:$('objective-debt'), toast:$('toast'), flash:$('hit-flash'), zone:$('zone-label'), contractMenu:$('contract-menu'), pause:$('pause-overlay') };
  const keys = new Set();
  const contracts = {fox:{name:'FOX DEVIL',symbol:'狐',cost:35,cool:4.2},future:{name:'FUTURE DEVIL',symbol:'未',cost:45,cool:7},blood:{name:'BLOOD DEVIL',symbol:'血',cost:50,cool:5},curse:{name:'CURSE DEVIL',symbol:'呪',cost:40,cool:5.5}};
  const platforms = [{x:205,y:186,w:105},{x:390,y:158,w:95},{x:585,y:188,w:120},{x:770,y:165,w:110},{x:960,y:185,w:105},{x:1150,y:157,w:120},{x:1360,y:183,w:110},{x:1555,y:158,w:120},{x:1770,y:185,w:110},{x:1950,y:160,w:110},{x:2150,y:183,w:120},{x:2320,y:160,w:130}];
  const mobSpots = [180,280,400,520,650,760,880,990,1110,1230,1350,1460,1580,1690,1800,1910,2020,2130,2240,2350,2420,850,1270,1740,2180,2300];
  let player,enemies,bullets,particles,camera,active,lastTime,elapsed,kills,cash,debt,chosenContract,weapon,cooldown,contractCooldown,toastTimer,soundOn=false,audio,bossSpawned,bossDead,shake,gameWon,paused,contractMenuOpen,stickDirection=0,combo,comboTimer;
  let best=Number(localStorage.getItem('debtCollectorBest')||0);
  const enemyColors=['#7a4d54','#64737c','#8b6048','#565c75','#68794e'];
  const zoneNames=['ZONE 01 — THE UNDERPASS','ZONE 02 — THE MEAT DISTRICT','ZONE 03 — THE BAT NEST'];
  function freshGame(){
    player={x:54,y:FLOOR-32,w:20,h:32,vx:0,vy:0,hp:5,maxHp:5,blood:100,maxBlood:100,face:1,ground:true,jumps:0,inv:0,anim:0,attack:0,future:0,dash:0,dashCooldown:0,dashDirection:1};
    enemies=mobSpots.map((x,i)=>({x,y:FLOOR-(i%5===1?24:25),w:i%5===1?22:21,h:i%5===1?24:25,hp:i%5===3?3:2,maxHp:i%5===3?3:2,alive:true,boss:false,kind:i%5,dir:-1,hit:0,attack:.6+Math.random()*1.5,anim:Math.random()*5,phase:Math.random()*6,home:x}));
    bullets=[];particles=[];camera=0;kills=0;cash=0;debt=8400;elapsed=0;cooldown=0;contractCooldown=0;toastTimer=0;bossSpawned=false;bossDead=false;shake=0;gameWon=false;weapon=1;chosenContract='fox';active=false;paused=false;contractMenuOpen=false;combo=0;comboTimer=0;
    document.querySelectorAll('.weapon-item').forEach((el,i)=>{el.classList.toggle('active',i===0);el.dataset.ready=i===0?'1':'';el.querySelector('.weapon-status').textContent=i===0?'EQUIPPED':'LOCKED'});
    document.querySelectorAll('.contract-card').forEach((el,i)=>el.classList.toggle('selected',i===0));
    ui.start.classList.remove('hidden');ui.result.classList.add('hidden');ui.controls.classList.remove('enabled');ui.boss.classList.add('hidden');ui.contractMenu.classList.add('hidden');ui.pause.classList.add('hidden');ui.zone.textContent=zoneNames[0];renderUI();
  }
  function money(n){return '¥ '+Math.max(0,Math.floor(n)).toLocaleString('en-US')}
  function renderUI(){
    ui.hearts.innerHTML='';for(let i=0;i<player.maxHp;i++){const h=document.createElement('span');h.className='heart'+(i>=player.hp?' empty':'');h.textContent='♥';ui.hearts.appendChild(h)}
    ui.hearts.setAttribute('aria-label',`${player.hp} of ${player.maxHp} health`);ui.health.textContent=`0${player.hp} / 0${player.maxHp}`;
    const blood=$('blood-meter');if(blood)blood.style.width=`${player.blood}%`;
    ui.debt.textContent=money(debt);ui.debtMeter.style.width=`${Math.max(0,debt/8400*100)}%`;ui.kills.innerHTML=`${String(Math.min(kills,27)).padStart(2,'0')} <small>/ 27</small>`;ui.cash.textContent=money(cash);ui.objKills.textContent=`${Math.min(kills,27)} / 27`;ui.objDebt.textContent=Math.floor(debt).toLocaleString('en-US');
    const boss=enemies.find(e=>e.boss&&e.alive);if(boss){ui.boss.classList.remove('hidden');ui.bossMeter.style.width=`${Math.max(0,boss.hp/boss.maxHp*100)}%`}else ui.boss.classList.add('hidden');
    const cfg=contracts[chosenContract],sym=$('ability-symbol'),name=$('ability-name'),cost=$('ability-cost'),cd=$('ability-cd');if(sym)sym.textContent=cfg.symbol;if(name)name.textContent=cfg.name;if(cost)cost.textContent=contractCooldown>0?`COOLDOWN ${contractCooldown.toFixed(1)}s`: `BLOOD ${cfg.cost} · ${player.blood>=cfg.cost?'READY':'LOW BLOOD'}`;if(cd)cd.style.width=`${contractCooldown>0?Math.max(0,contractCooldown/cfg.cool*100):0}%`;
    const comboEl=$('combo-display');if(comboEl)comboEl.classList.toggle('show',combo>=2&&comboTimer>0);const comboVal=$('combo-value');if(comboVal)comboVal.textContent=`x${Math.max(2,combo)}`;
  }
  function showToast(message){ui.toast.textContent=message;ui.toast.classList.add('show');toastTimer=1.6}
  function startGame(){if(active)return;active=true;paused=false;ui.start.classList.add('hidden');ui.controls.classList.add('enabled');lastTime=performance.now();audioUnlock();showToast('CONTRACT ACCEPTED — GO TO WORK')}
  function startResult(won){active=false;paused=false;contractMenuOpen=false;gameWon=won;ui.controls.classList.remove('enabled');ui.pause.classList.add('hidden');ui.contractMenu.classList.add('hidden');ui.result.classList.remove('hidden');$('result-kicker').textContent=won?'MISSION COMPLETE':'CONTRACT TERMINATED';$('result-title').innerHTML=won?'NICE WORK,<br>HUNTER.':'YOU OWE<br>THEM MORE.';$('result-copy').textContent=won?'Three floors cleared. The debt is somebody else’s problem.':`You exorcised ${kills} devil${kills===1?'':'s'} before clocking out.`;$('result-kills').textContent=String(kills).padStart(2,'0');$('result-cash').textContent=money(cash);if(won&&cash>best){best=cash;localStorage.setItem('debtCollectorBest',best)}playTone(won?520:130,.18,'triangle')}
  function audioUnlock(){if(!soundOn)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume()}catch(e){}}
  function playTone(freq,duration=.08,type='square'){if(!soundOn)return;try{audioUnlock();if(!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}catch(e){}}
  function puff(x,y,color,n=8){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*100,vy:(Math.random()-.8)*100,life:.25+Math.random()*.42,color,size:2+Math.random()*3})}
  function hitPlayer(damage){if(player.inv>0||player.future>0||!active)return;player.hp=Math.max(0,player.hp-damage);player.blood=Math.min(100,player.blood+8);player.inv=1.05;shake=5;ui.flash.classList.remove('active');void ui.flash.offsetWidth;ui.flash.classList.add('active');puff(player.x+10,player.y+13,'#ed5a4b',11);playTone(90,.18,'sawtooth');renderUI();if(player.hp<=0)startResult(false)}
