    document.querySelectorAll('.contract-card').forEach(el=>el.addEventListener('click',()=>selectContract(el.dataset.contract)));document.querySelectorAll('.quick-contract').forEach(el=>el.addEventListener('click',()=>selectContract(el.dataset.quickContract)));document.querySelectorAll('.weapon-item').forEach(el=>el.addEventListener('click',()=>selectWeapon(Number(el.dataset.weapon))));
