:root{color-scheme:dark;--bg:#101114;--panel:#17181b;--panel2:#1d1e22;--line:#303136;--muted:#85858a;--paper:#efeee9;--red:#df4137;--mono:'DM Mono',monospace;--sans:'Space Grotesk',sans-serif}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--paper);font-family:var(--sans);min-height:100vh;background-image:radial-gradient(ellipse at 50% -28%,#2c2928 0,transparent 58%)}
button{font:inherit;color:inherit}
.app-shell{max-width:1440px;margin:auto;padding:0 40px}
.topbar{height:66px;border-bottom:1px solid #2b2b2e;display:flex;align-items:center;justify-content:space-between;font:10px var(--mono);letter-spacing:.11em;color:#c2c1bc}
.brand{display:flex;align-items:center;gap:11px;color:#f6f5f0;text-decoration:none;font:700 12px var(--sans);letter-spacing:.08em}
.brand-mark{background:var(--red);width:29px;height:29px;display:grid;place-items:center;font-size:13px;letter-spacing:0}
.brand-light{font-weight:400;color:#96969a}
.topbar-center{color:#99999c}
.live-dot,.status-pill i{display:inline-block;width:6px;height:6px;background:#a5c66c;border-radius:50%;margin-right:8px;box-shadow:0 0 8px #a5c66c}
.top-sep{color:#555;margin:0 8px}
.topbar-right{display:flex;align-items:center;gap:12px}
.dispatch-label{color:#747478}
.dispatch-signal{color:#9fc373;font-size:8px;letter-spacing:2px}
.agent-id{border-left:1px solid #39393d;padding-left:13px;color:#c9c8c2}
.intro-row{display:flex;justify-content:space-between;align-items:center;padding:35px 0 25px}
.eyebrow,.stamp-label,.stamp-code,.panel-heading,.frame-top,.frame-bottom,.control-strip,.page-footer{font-family:var(--mono);letter-spacing:.1em}
.eyebrow{font-size:9px;color:#aaa9a4;display:flex;align-items:center;gap:9px}
.eyebrow-line{height:1px;width:20px;background:var(--red)}
h1{font-size:clamp(35px,4vw,54px);line-height:.98;letter-spacing:-.06em;margin:12px 0 9px;font-weight:700}
.title-cut{color:var(--red);position:relative}
.subtitle{margin:0;color:#929196;font-size:13px}
.mission-stamp{border:1px solid #38383b;padding:12px 16px;min-width:174px;position:relative;transform:rotate(1deg)}
.mission-stamp:after{content:'';position:absolute;inset:4px;border:1px solid #29292d;pointer-events:none}
.stamp-label,.stamp-code{display:block;color:#8c8b90;font-size:8px}
.mission-stamp strong{display:block;font-size:12px;line-height:1.35;letter-spacing:.08em;margin:6px 0}
.stamp-code{color:#b34b44}
.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:19px;align-items:stretch}
.game-column{min-width:0}
.game-frame{border:1px solid #3a3a3e;background:#17181a;padding:7px}
.frame-top,.frame-bottom{height:27px;display:flex;align-items:center;justify-content:space-between;padding:0 9px;color:#c7c6c1;font-size:8px}
.frame-muted{color:#747479}
.frame-coords{color:#77777b}
.tiny-square{display:inline-block;width:6px;height:6px;background:var(--red);margin-right:7px}
.viewport{width:100%;aspect-ratio:16/9;position:relative;overflow:hidden;background:#1a1b22;image-rendering:pixelated}
.viewport canvas{display:block;width:100%;height:100%;image-rendering:pixelated}
.hud{position:absolute;color:#fff;text-shadow:1px 1px #17171a;font:9px var(--mono);pointer-events:none}
.hud-left{left:13px;top:11px}
.hud-right{right:13px;top:11px;text-align:right}
.hud-kicker{display:block;color:#d9d4ca;font-size:7px;letter-spacing:.1em}
.hud-kicker span{color:white;margin-left:5px}
.hearts{display:flex;gap:3px;margin-top:5px}
.heart{color:#ec534c;font-size:14px;line-height:1;text-shadow:0 1px #721f1d}
.heart.empty{color:#45414a}
.debt-track,.boss-track{height:4px;background:#4a3231;margin-top:5px;width:96px}
.debt-track span{height:100%;display:block;background:var(--red);width:100%;transition:width .3s}
.hud-bottom-left{bottom:12px;left:13px}
.hud-bottom-right{bottom:12px;right:13px;text-align:right}
.hud-bottom-left strong,.hud-bottom-right strong{font-size:13px;display:block;margin-top:2px}
.hud-bottom-left small{font-size:8px;color:#c6c3bd}
.boss-bar{position:absolute;top:14px;left:50%;transform:translateX(-50%);width:43%;text-align:center;font:8px var(--mono);color:#fff;text-shadow:1px 1px #000}
.boss-name{letter-spacing:.12em}
.boss-name>span{color:#f35a49}
.boss-class{color:#d39a82}
.boss-track{width:100%;height:5px;background:#423439}
.boss-track i{height:100%;width:100%;display:block;background:#e14c40;transition:width .25s}
.hidden{display:none!important}
.screen-overlay,.result-overlay{position:absolute;inset:0;display:grid;place-items:center;background:rgba(10,11,15,.55);text-align:center}
.screen-overlay{background:linear-gradient(90deg,rgba(10,11,15,.48),rgba(10,11,15,.17) 53%,rgba(10,11,15,.4))}
.overlay-noise{position:absolute;inset:0;opacity:.11;background:repeating-linear-gradient(0deg,transparent 0 3px,#fff 4px);pointer-events:none}
.screen-overlay>*:not(.overlay-noise){position:absolute}
.classified{top:13px;left:15px;right:15px;display:flex;justify-content:space-between;font:7px var(--mono);letter-spacing:.11em;color:#c4c0b9}
.overlay-sigil{top:22%;right:12%;color:rgba(236,226,209,.13);font-size:74px;font-weight:700;transform:rotate(-12deg)}
.overlay-kicker{top:24%;left:0;right:0;font:8px var(--mono);letter-spacing:.2em;color:#d1ccc1}
.screen-overlay h2{left:0;right:0;top:30%;font-size:clamp(29px,5vw,47px);line-height:.88;letter-spacing:-.06em;margin:0;text-shadow:3px 4px #17171a}
.screen-overlay h2 em{font-style:normal;color:var(--red)}
.overlay-copy{top:55%;left:0;right:0;color:#ddd9d2;font-size:10px;line-height:1.6}
.start-button{background:var(--red);border:0;padding:12px 17px;font:500 9px var(--mono);letter-spacing:.08em;cursor:pointer;box-shadow:3px 3px 0 #631e1b;transition:transform .15s,background .15s}
.start-button:hover{background:#f15a4f;transform:translateY(-2px)}
.start-button span{font-size:15px;margin-left:15px}
.screen-overlay .start-button{top:72%}
.overlay-foot{bottom:13px;left:0;right:0;display:flex;gap:21px;justify-content:center;color:#e3ddd1;font:7px var(--mono);letter-spacing:.06em}
.result-overlay{background:rgba(12,12,16,.72)}
.result-card{background:#17181c;border:1px solid #4a4544;padding:22px;min-width:245px;box-shadow:6px 7px 0 rgba(0,0,0,.35)}
.result-kicker{color:#b1cc78;font:8px var(--mono);letter-spacing:.18em}
.result-card h2{font-size:27px;line-height:.95;margin:12px 0}
.result-card p{color:#a6a4a4;font-size:10px}
.result-stats{display:flex;justify-content:space-between;border-top:1px solid #343438;border-bottom:1px solid #343438;padding:9px 0;margin:13px 0;color:#929197;font:8px var(--mono)}
.result-stats b{color:#eee;margin-left:5px}
.result-card .start-button{width:100%}
.toast{position:absolute;top:46%;left:50%;transform:translate(-50%,-50%);background:rgba(15,15,18,.9);border:1px solid #bd443b;padding:8px 13px;color:white;font:9px var(--mono);letter-spacing:.08em;opacity:0;transition:opacity .2s;pointer-events:none;white-space:nowrap}
.toast.show{opacity:1}
.hit-flash{position:absolute;inset:0;background:rgba(220,45,38,.22);opacity:0;pointer-events:none}
.hit-flash.active{animation:flash .2s}
@keyframes flash{50%{opacity:1}
}
.signal-bars{color:#95c46d;letter-spacing:-2px;margin-right:5px}
.control-strip{display:flex;align-items:center;gap:7px;flex-wrap:wrap;padding:11px 6px;color:#a6a5a1;font-size:8px}
.control-label{color:#eee;font-size:8px;margin-right:5px}
.control-strip kbd{font:8px var(--mono);padding:3px 5px;background:#242529;border:1px solid #3a3a3e;color:#ddd;margin-right:2px}
.sound-toggle{margin-left:auto;background:none;border:0;color:#a7a5a0;font:8px var(--mono);letter-spacing:.06em;cursor:pointer;padding:4px}
.sound-toggle:hover{color:white}
.intel-panel{border:1px solid #303034;background:linear-gradient(145deg,#191a1d,#151619);display:flex;flex-direction:column}
.panel-block{padding:15px 16px;border-bottom:1px solid #303034}
.panel-heading{display:flex;align-items:center;justify-content:space-between;color:#929197;font-size:8px}
.status-pill{font-size:7px;color:#b1c88a;border:1px solid #3b4731;padding:3px 6px}
.status-pill i{width:5px;height:5px;margin-right:4px}
.mission-block h2{font-size:22px;line-height:.95;letter-spacing:-.04em;margin:17px 0 8px}
.mission-block>p{font-size:10px;color:#99989b;line-height:1.5;margin:0 0 13px}
.objective{height:29px;border-top:1px solid #2c2d31;display:flex;align-items:center;gap:8px;font:8px var(--mono);color:#aaa9ad}
.objective-icon{font-size:15px;color:#e25449}
.objective-icon.yen{font-size:13px;font-weight:700}
.objective strong{margin-left:auto;color:#e5e3dd;font-size:9px}
.risk-label{font-size:7px;color:#c77866}
.contract-block{padding-top:13px;padding-bottom:12px}
.contract-card{margin-top:8px;width:100%;height:44px;background:#1c1d21;border:1px solid #303136;display:flex;align-items:center;text-align:left;padding:5px 8px;gap:9px;cursor:pointer;transition:border-color .15s,background .15s}
.contract-card:hover,.contract-card.selected{border-color:#9c4a43;background:#242023}
.contract-symbol{width:28px;height:28px;display:grid;place-items:center;font-size:15px;background:#282529;color:#dd655b}
.future-symbol{color:#b4c37b}
.blood-symbol{color:#d7534b}
.contract-info{display:flex;flex-direction:column;gap:3px}
.contract-info strong{font:500 9px var(--mono);letter-spacing:.04em}
.contract-info small{font:7px var(--mono);color:#99989d}
.contract-key{margin-left:auto;border:1px solid #45454a;padding:3px 6px;color:#d4d1cb;font:8px var(--mono)}
.contract-note{font:7px var(--mono);color:#77777c;text-align:right;margin-top:9px}
.contract-note b{color:#bbb}
.ammo-label{font-size:7px;color:#89a36e}
.weapon-block{padding-top:13px;padding-bottom:10px}
.weapon-list{margin-top:8px}
.weapon-item{width:100%;height:40px;display:flex;align-items:center;gap:8px;text-align:left;background:transparent;border:0;border-top:1px solid #2c2d30;padding:3px 2px;cursor:pointer;color:#bbb}
.weapon-item:hover,.weapon-item.active{color:#f0eee7}
.weapon-number{font:8px var(--mono);color:#777}
.weapon-icon{width:24px;text-align:center;color:#d45a4e;font-size:17px}
.chainsaw-icon{transform:rotate(-40deg);font-size:22px}
.gun-icon{font-size:13px}
.weapon-item>span:nth-last-child(2){display:flex;flex-direction:column;gap:2px}
.weapon-item strong{font:8px var(--mono);color:#ddd}
.weapon-item small{font:7px var(--mono);color:#929196}
.weapon-status{margin-left:auto;font:6px var(--mono);letter-spacing:.06em;color:#b6ca82}
.weapon-status.locked{color:#79797d}
.tip-card{margin:auto 11px 11px;display:flex;gap:9px;align-items:center;background:#202023;border:1px solid #303034;padding:10px}
.tip-mark{width:19px;height:19px;display:grid;place-items:center;color:#e0a163;border:1px solid #77553b;font:bold 11px var(--mono)}
.tip-card p{font-size:8px;color:#aaa9aa;line-height:1.5;margin:0}
.tip-card strong{color:#ddd6ca;font:8px var(--mono);letter-spacing:.1em}
.page-footer{display:flex;justify-content:space-between;padding:15px 0 19px;border-top:1px solid #292a2d;color:#66666b;font-size:7px}
.page-footer b{color:#96b769;margin-left:3px}
@media(max-width:900px){.app-shell{padding:0 20px}
.game-layout{grid-template-columns:minmax(0,1fr) 270px;gap:12px}
.panel-block{padding-left:12px;padding-right:12px}
