.page-footer{font-size:6px}
}
@media(max-width:700px){.virtual-controls{visibility:hidden}
.virtual-controls.enabled{visibility:visible}
.virtual-controls{position:absolute;z-index:4;inset:auto 10px 8px;display:flex;align-items:flex-end;justify-content:space-between;pointer-events:none;touch-action:none;user-select:none;-webkit-user-select:none}
.virtual-stick{position:relative;width:108px;height:66px;display:flex;align-items:center;justify-content:space-between;padding:0 12px;border:1px solid rgba(238,232,218,.42);border-radius:999px;background:rgba(20,21,26,.64);color:rgba(255,255,255,.72);font:11px var(--mono);pointer-events:auto;touch-action:none;box-shadow:inset 0 0 18px rgba(0,0,0,.26)}
.virtual-stick.engaged{border-color:rgba(238,232,218,.8);background:rgba(32,32,37,.82)}
.stick-thumb{position:absolute;left:50%;top:50%;width:35px;height:35px;transform:translate(-50%,-50%);border:1px solid rgba(255,255,255,.72);border-radius:50%;background:rgba(220,218,210,.82);box-shadow:0 2px 9px #0008;pointer-events:none}
.stick-left,.stick-right{z-index:1;pointer-events:none}
.virtual-actions{display:flex;align-items:flex-end;gap:7px;pointer-events:none}
.virtual-button{width:44px;height:44px;padding:0;display:grid;place-items:center;border:1px solid rgba(255,255,255,.65);border-radius:50%;background:rgba(35,34,39,.78);color:#fff;font:700 14px var(--mono);text-shadow:0 1px 3px #000;pointer-events:auto;touch-action:none;box-shadow:0 2px 8px #0007}
.virtual-button:active{transform:scale(.94);background:rgba(180,58,51,.88)}
.jump-button{width:38px;height:38px;margin-bottom:3px}
.contract-button{width:38px;height:38px;margin-bottom:3px;color:#f0bb83}
.hud-bottom-left,.hud-bottom-right{bottom:82px}
.boss-bar{top:48px}
.virtual-controls button:focus-visible,.virtual-stick:focus-visible{outline:2px solid #e8b178;outline-offset:2px}
}
@media(max-width:360px){.virtual-controls{inset-inline:7px;bottom:6px}
