.virtual-button,.jump-button,.contract-button{width:32px;height:32px;margin:0;font-size:10px}
.attack-button{border-color:rgba(223,65,55,.9);background:rgba(143,43,39,.88)}
.contract-button,.pause-button{font-size:8px}
.hud-bottom-left,.hud-bottom-right{bottom:83px}
}

@media(max-width:360px){.virtual-controls{inset-inline:6px;gap:5px;bottom:6px}
.virtual-stick{flex-basis:76px;width:76px;height:54px}
