const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, executablePath: process.env.CHROME_BIN || '/usr/bin/google-chrome', args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 900 }, deviceScaleFactor: 1 });
const errors=[];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if(m.type()==='error') errors.push(m.text()); });
await page.goto('http://127.0.0.1:3000', {waitUntil:'domcontentloaded'});
await page.locator('#start-button').click();
await page.waitForTimeout(300);
await page.keyboard.press('d'); await page.keyboard.press('Space'); await page.keyboard.press('Shift'); await page.keyboard.press('j');
await page.locator('[data-contract="blood"]').click();
await page.keyboard.press('k');
await page.keyboard.press('Escape');
const desktop = await page.evaluate(() => ({
  title: document.title,
  started: document.querySelector('#start-overlay').classList.contains('hidden'),
  selectedContract: document.querySelector('.contract-card.selected')?.dataset.contract,
  bloodMeter: document.querySelector('#blood-meter').style.width,
  paused: !document.querySelector('#pause-overlay').classList.contains('hidden'),
  layoutOverflow: document.documentElement.scrollWidth > innerWidth,
  viewport: document.querySelector('#viewport').getBoundingClientRect().toJSON(),
}));
await page.locator('#resume-button').click();
await page.screenshot({path:'/tmp/opencode/debt-collector-latest.jpg', type:'jpeg', quality:82});
await page.setViewportSize({width:390,height:844});
await page.waitForTimeout(150);
const mobile = await page.evaluate(() => ({
  overflow: document.documentElement.scrollWidth > innerWidth,
  viewport: document.querySelector('#viewport').getBoundingClientRect().toJSON(),
  controlsVisible: getComputedStyle(document.querySelector('#virtual-controls')).visibility,
  controlsEnabled: document.querySelector('#virtual-controls').classList.contains('enabled'),
  layoutColumns: getComputedStyle(document.querySelector('.game-layout')).gridTemplateColumns,
}));
await page.locator('#touch-jump').dispatchEvent('click');
await page.waitForTimeout(100);
console.log(JSON.stringify({desktop,mobile,errors},null,2));
await browser.close();
