await page.locator('#touch-pause').tap();
const paused = !await page.locator('#pause-overlay').evaluate(el => el.classList.contains('hidden'));
await page.locator('#resume-button').tap();
console.log(JSON.stringify({menuOpened,paused,blood:await page.locator('#blood-meter').evaluate(el=>el.style.width),errors,overflow:await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth)}));
